// ==================== БАЗА (Master) ====================
#define _LCD_TYPE 1
#include <LCD_1602_RUS_ALL.h>
#include <SoftwareSerial.h>
#include <EEPROM.h>
#include <SoftwareSerialTX.h>

// ---------- LCD ----------
LCD_1602_RUS lcd(0x27, 16, 2);

// ---------- RS485 (SoftwareSerial) ----------
SoftwareSerial rs485(10, 11);       // RX = D10, TX = D11
const int RS485_DE_RE = 2;

// ---------- Джойстик ----------
const int JOY_X = A0;
const int JOY_Y = A1;
const int JOY_BTN = 3;

// ---------- Состояние ----------
int angleH = 90;
int angleV = 90;
int azimuth = 0;
int targetAzimuth = 0;
int targetH = 90;
int targetV = 90;
bool hasMemory = false;
bool stabilizationMode = false;

// ---------- Кнопка ----------
bool lastBtn = HIGH;
unsigned long lastDebounce = 0;
unsigned long btnPressStart = 0;
bool longPressHandled = false;

// ---------- EEPROM ----------
const int EEPROM_MAGIC = 0;
const int EEPROM_AZ = 2;
const int EEPROM_H = 4;
const int EEPROM_V = 6;
const int EEPROM_MAGIC_VALUE = 0xAB;

// ---------- Тайминги ----------
unsigned long lastSend = 0;
const int SEND_INTERVAL = 50;
unsigned long lastLcd = 0;
const int LCD_INTERVAL = 300;
unsigned long lastReadRS = 0;
const int RS_READ_INTERVAL = 20;
unsigned long lastAzReceived = 0;

// ---------- Приём RS485 ----------
String rxBuffer = "";

void setup() {
    Serial.begin(9600);
    rs485.begin(9600);
    pinMode(RS485_DE_RE, OUTPUT);
    digitalWrite(RS485_DE_RE, LOW);
    pinMode(JOY_BTN, INPUT_PULLUP);

    lcd.init();
    lcd.backlight();
    lcd.clear();
    lcd.print(F("База готова"));
    delay(1000);

    loadMemory();
    Serial.println(F("=== BASE READY ==="));
}

void loop() {
    unsigned long now = millis();

    if (now - lastReadRS >= RS_READ_INTERVAL) {
        lastReadRS = now;
        readRS485();
    }

    handleButton();
    manualControl();

    if (now - lastSend >= SEND_INTERVAL) {
        lastSend = now;
        sendAngles();
    }

    if (now - lastLcd >= LCD_INTERVAL) {
        lastLcd = now;
        updateDisplay();
    }
}

// ==================== ЧТЕНИЕ RS485 ====================
void readRS485() {
    while (rs485.available()) {
        char c = rs485.read();
        if (c == '\n') {
            parsePacket(rxBuffer);
            rxBuffer = "";
        } else {
            rxBuffer += c;
            if (rxBuffer.length() > 32) rxBuffer = "";
        }
    }
}

void parsePacket(String p) {
    p.trim();
    if (p.startsWith("A:")) {
        azimuth = p.substring(2).toInt();
        if (azimuth < 0) azimuth += 360;
        lastAzReceived = millis();
        Serial.print(F("RX Azimuth: "));
        Serial.println(azimuth);
    }
}

// ==================== ДЖОЙСТИК ====================
void manualControl() {
    int jx = analogRead(JOY_X);
    int jy = analogRead(JOY_Y);

    if (jx < 400) angleH = constrain(angleH - 2, 0, 180);
    else if (jx > 600) angleH = constrain(angleH + 2, 0, 180);

    if (jy < 400) angleV = constrain(angleV - 2, 0, 180);
    else if (jy > 600) angleV = constrain(angleV + 2, 0, 180);

    if (abs(jx - 512) > 100 || abs(jy - 512) > 100) {
        if (stabilizationMode) {
            stabilizationMode = false;
            sendStabMode(0);
            Serial.println(F("Exit stabilization - manual mode"));
        }
    }
}

// ==================== ОТПРАВКА КОМАНД ====================
void sendAngles() {
    String cmd = "H:";
    cmd += padNum(angleH, 3);
    cmd += "V:";
    cmd += padNum(angleV, 3);
    cmd += "\n";
    sendRS485(cmd);
}

void sendStabMode(int on) {
    String cmd = "S:";
    cmd += String(on);
    cmd += "\n";
    sendRS485(cmd);
}

void sendTargetAz(int az) {
    String cmd = "T:";
    cmd += padNum(az, 3);
    cmd += "\n";
    sendRS485(cmd);
}

void sendCalibrate() {
    sendRS485("C:000\n");
}

void sendRS485(String data) {
    Serial.print(F("TX: "));
    Serial.print(data);
    digitalWrite(RS485_DE_RE, HIGH);
    delayMicroseconds(50);
    rs485.print(data);
    rs485.flush();
    delayMicroseconds(50);
    digitalWrite(RS485_DE_RE, LOW);
}

// ==================== КНОПКА ====================
void handleButton() {
    bool btn = digitalRead(JOY_BTN);
    unsigned long now = millis();

    if (btn != lastBtn) lastDebounce = now;

    if ((now - lastDebounce) > 50) {
        if (btn == LOW && lastBtn == HIGH) {
            btnPressStart = now;
            longPressHandled = false;
        }

        if (btn == LOW && !longPressHandled) {
            unsigned long held = now - btnPressStart;
            if (held > 5000) {
                lcd.clear();
                lcd.print(F("Калибровка..."));
                sendCalibrate();
                longPressHandled = true;
                Serial.println(F("Command: CALIBRATE"));
            } else if (held > 1500) {
                clearMemory();
                longPressHandled = true;
            }
        }

        if (btn == HIGH && lastBtn == LOW) {
            if (!longPressHandled && (now - btnPressStart) > 50) {
                savePosition();
            }
        }
    }
    lastBtn = btn;
}

// ==================== ПАМЯТЬ ====================
void savePosition() {
    targetAzimuth = azimuth;
    targetH = angleH;
    targetV = angleV;
    hasMemory = true;
    stabilizationMode = true;

    EEPROM.write(EEPROM_AZ, targetAzimuth);
    EEPROM.write(EEPROM_H, targetH);
    EEPROM.write(EEPROM_V, targetV);
    EEPROM.write(EEPROM_MAGIC, EEPROM_MAGIC_VALUE);

    sendTargetAz(targetAzimuth);
    sendStabMode(1);

    lcd.clear();
    lcd.print(F("СОХРАНЕНО!"));
    lcd.setCursor(0, 1);
    lcd.print(F("Аз:"));
    lcd.print(padNum(targetAzimuth, 3));
    delay(1200);

    Serial.print(F("SAVED: Az="));
    Serial.print(targetAzimuth);
    Serial.print(F(" H="));
    Serial.print(targetH);
    Serial.print(F(" V="));
    Serial.println(targetV);
}

void loadMemory() {
    if (EEPROM.read(EEPROM_MAGIC) == EEPROM_MAGIC_VALUE) {
        targetAzimuth = EEPROM.read(EEPROM_AZ);
        targetH = EEPROM.read(EEPROM_H);
        targetV = EEPROM.read(EEPROM_V);
        if (targetAzimuth >= 0 && targetAzimuth <= 359) {
            hasMemory = true;
            Serial.print(F("Memory loaded: Az="));
            Serial.println(targetAzimuth);
        }
    } else {
        Serial.println(F("No memory in EEPROM"));
    }
}

void clearMemory() {
    EEPROM.write(EEPROM_MAGIC, 0);
    hasMemory = false;
    stabilizationMode = false;
    sendStabMode(0);

    lcd.clear();
    lcd.print(F("ПАМЯТЬ ОЧИЩЕНА"));
    delay(1000);
    Serial.println(F("MEMORY CLEARED"));
}

// ==================== LCD ====================
void updateDisplay() {
    lcd.setCursor(0, 0);
    lcd.print(F("Аз:"));
    lcd.print(padNum(azimuth, 3));
    lcd.print(F("\xDF"));
    lcd.print(F(" "));

    if (stabilizationMode) lcd.print(F("ФИКС"));
    else if (hasMemory)    lcd.print(F("ПАМ "));
    else                   lcd.print(F("СВОБ"));

    lcd.setCursor(0, 1);
    lcd.print(F("Г:"));
    lcd.print(padNum(angleH, 3));
    lcd.print(F(" В:"));
    lcd.print(padNum(angleV, 3));
}

// ==================== УТИЛИТЫ ====================
String padNum(int v, byte w) {
    String s = String(v);
    while (s.length() < w) s = "0" + s;  // ✅ ИСПРАВЛЕНО: нули вместо пробелов
    return s;
}
